-- A. Changed rows ko expire karo
UPDATE dbo.DimCustomer
SET    EndDate   = CAST(GETDATE() AS DATE),
       IsCurrent = 0
WHERE  IsCurrent = 1
  AND EXISTS
  (
      SELECT 1
      FROM   dbo.Customer_Source s
      WHERE  s.CustomerID = dbo.DimCustomer.CustomerID
        AND (   ISNULL(s.CustomerName,'') <> ISNULL(dbo.DimCustomer.CustomerName,'')
             OR ISNULL(s.City,'')         <> ISNULL(dbo.DimCustomer.City,'')
             OR ISNULL(s.MobileNumber,'') <> ISNULL(dbo.DimCustomer.MobileNumber,'') )
  );





  -- B. Naye aur changed customers ka current row insert karo
INSERT INTO dbo.DimCustomer
       (CustomerID, CustomerName, City, MobileNumber, StartDate, EndDate, IsCurrent)
SELECT s.CustomerID, s.CustomerName, s.City, s.MobileNumber,
       CAST(GETDATE() AS DATE), NULL, 1
FROM   dbo.Customer_Source s
WHERE  NOT EXISTS
(
    SELECT 1
    FROM   dbo.DimCustomer d
    WHERE  d.CustomerID = s.CustomerID
      AND  d.IsCurrent  = 1
);


SELECT * FROM dbo.DimCustomer ORDER BY CustomerID, StartDate;


